package com.cyberworkspace.app.net

import android.content.Context
import android.content.SharedPreferences
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey
import kotlinx.serialization.builtins.ListSerializer
import kotlinx.serialization.builtins.serializer
import kotlinx.serialization.json.Json

/**
 * Encrypted storage for pairing credentials (PROTOCOL.md §4): device id, bearer
 * token, pinned certificate fingerprint and granted permissions. The token is
 * generated by the host and travels exactly once in `pairing_ok`; it is stored
 * here and nowhere else. Master key: AES256_GCM in the Android keystore.
 */
class AuthStore(context: Context) {

    private val json = Json { ignoreUnknownKeys = true }
    private val stringList = ListSerializer(String.serializer())
    private val prefs: SharedPreferences

    init {
        val masterKey = MasterKey.Builder(context)
            .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
            .build()
        prefs = EncryptedSharedPreferences.create(
            context,
            PREFS_NAME,
            masterKey,
            EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
            EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
        )
    }

    var deviceId: String
        get() = prefs.getString(KEY_DEVICE_ID, null) ?: ""
        set(value) = prefs.edit().putString(KEY_DEVICE_ID, value).apply()

    var token: String
        get() = prefs.getString(KEY_TOKEN, null) ?: ""
        set(value) = prefs.edit().putString(KEY_TOKEN, value).apply()

    var fingerprint: String
        get() = prefs.getString(KEY_FINGERPRINT, null) ?: ""
        set(value) = prefs.edit().putString(KEY_FINGERPRINT, value).apply()

    /** Permissions granted at pairing: ["view"] or ["view", "control"] (§1). */
    var permissions: List<String>
        get() = prefs.getString(KEY_PERMISSIONS, null)?.let { raw ->
            runCatching { json.decodeFromString(stringList, raw) }.getOrDefault(emptyList())
        } ?: emptyList()
        set(value) = prefs.edit()
            .putString(KEY_PERMISSIONS, json.encodeToString(stringList, value))
            .apply()

    val hasCredentials: Boolean
        get() = deviceId.isNotBlank() && token.isNotBlank()

    val hasFingerprint: Boolean
        get() = fingerprint.isNotBlank()

    fun isPaired(): Boolean = hasCredentials && hasFingerprint

    fun hasPermission(name: String): Boolean = permissions.contains(name)

    /** Persist everything returned by `pairing_ok` in one atomic write. */
    fun save(deviceId: String, token: String, fingerprint: String, permissions: List<String>) {
        prefs.edit()
            .putString(KEY_DEVICE_ID, deviceId)
            .putString(KEY_TOKEN, token)
            .putString(KEY_FINGERPRINT, fingerprint)
            .putString(KEY_PERMISSIONS, json.encodeToString(stringList, permissions))
            .apply()
    }

    /** Wipe credentials (re-pairing, revocation, user logout). */
    fun clear() {
        prefs.edit().clear().apply()
    }

    private companion object {
        const val PREFS_NAME = "cyber_workspace_auth"
        const val KEY_DEVICE_ID = "device_id"
        const val KEY_TOKEN = "token"
        const val KEY_FINGERPRINT = "fingerprint"
        const val KEY_PERMISSIONS = "permissions"
    }
}
